parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["FAQ", "Account/Verification", "Payment/Billing", "Technical/Bug", "Resale/Transfer", "Feedback"],
      "description": "The primary support category based on what action is needed to resolve the message"
    },
    "sentiment": {
      "type": "string",
      "enum": ["positive", "neutral", "frustrated", "angry"],
      "description": "The emotional tone of the message"
    },
    "confidence": {
      "type": "number",
      "description": "Classification confidence from 0.0 to 1.0"
    },
    "rationale": {
      "type": "string",
      "description": "Brief explanation of why this category was chosen"
    }
  },
  "required": ["category", "sentiment", "confidence", "rationale"]
}

